import unittest
from candidate import largest_divisor

class TestLargestDivisor(unittest.TestCase):
    def test_normal_case_known_divisor(self):
        self.assertEqual(largest_divisor(15), 5)

    def test_prime_number_returns_one(self):
        self.assertEqual(largest_divisor(13), 1)

    def test_smallest_prime_returns_one(self):
        self.assertEqual(largest_divisor(2), 1)

    def test_even_number(self):
        self.assertEqual(largest_divisor(12), 6)

    def test_large_number(self):
        self.assertEqual(largest_divisor(100), 50)

    def test_zero_input_returns_none(self):
        self.assertIsNone(largest_divisor(0))

    def test_negative_input_returns_none(self):
        self.assertIsNone(largest_divisor(-5))

    def test_none_input_type_error(self):
        with self.assertRaises(TypeError):
            largest_divisor(None)

    def test_string_input_type_error(self):
        with self.assertRaises(TypeError):
            largest_divisor("10")

    def test_float_input_type_error(self):
        with self.assertRaises(TypeError):
            largest_divisor(10.5)

    def test_return_type_is_int(self):
        self.assertIsInstance(largest_divisor(30), int)

    def test_divides_evenly_and_smaller_than_n(self):
        n = 84
        divisor = largest_divisor(n)
        self.assertLess(divisor, n)
        self.assertEqual(n % divisor, 0)

    def test_zero_division_error_for_n_one(self):
        with self.assertRaises(ZeroDivisionError):
            largest_divisor(1)

if __name__ == "__main__":
    unittest.main()
